-- 來源: MyFitnessCoachDb_03171829.sql (2026/3/17 18:29)
-- 目標: MyFitnessCoachDb (Server=.\sql2025)
-- 同步範圍: Users, Roles, UserRoles, Departments, Employees,
--           LeaveTypes, LeaveRequests, LeaveBalances, LeaveAttachments
-- 建立日期: 2026/3/18
-- 注意: 請先備份資料庫再執行此腳本!
-- =====================================================

USE [MyFitnessCoachDb]
GO

-- =====================================================
-- 差異分析摘要:
-- =====================================================
-- 【Schema 差異】(SQL 檔案 vs EF Model 定義)
--
-- 1. [LeaveTypes] 缺少欄位:
--    - QuotaType nvarchar (EF Model 中有 PreAllocated/Unlimited/ApprovalRequired)
--    - WarnThresholdDays int (EF Model 中有)
--    -> 若程式需要這些功能，需另外 ALTER TABLE 新增欄位
--
-- 2. 缺少資料表 (EF Model 有定義，SQL 檔案中不存在):
--    - [Holidays] (Id, HolidayDate, Name, Year, IsActive)
--    - [LeaveBalanceHistory] (Id, LeaveBalanceId, ChangeType, ChangeDays, ...)
--    - [LeaveApprovalDelegation] (Id, ManagerEmployeeId, DelegateEmployeeId, ...)
--    -> 若程式需要這些資料表，需另外執行 CREATE TABLE
--
-- 【資料同步】
-- 本腳本會對以下 9 張表進行 DELETE + 重新 INSERT，
-- 確保資料庫的資料與 SQL 檔案完全一致:
--   Users, Roles, UserRoles, Departments, Employees,
--   LeaveTypes, LeaveRequests, LeaveBalances, LeaveAttachments
-- =====================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;
BEGIN TRY

    PRINT N'=== Step 1: 停用所有外鍵約束 ===';

    -- 動態停用資料庫中所有外鍵約束 (避免因約束名稱不同而失敗)
    DECLARE @sql NVARCHAR(MAX) = N'';
    SELECT @sql = @sql + N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id))
        + N'.' + QUOTENAME(OBJECT_NAME(parent_object_id))
        + N' NOCHECK CONSTRAINT ' + QUOTENAME(name) + N';' + CHAR(13)
    FROM sys.foreign_keys;
    EXEC sp_executesql @sql;

    PRINT N'  所有外鍵約束已停用';

    PRINT N'=== Step 2: 清除目標資料表 (反向相依順序) ===';

    DELETE FROM [dbo].[LeaveAttachments];
    PRINT N'  LeaveAttachments 已清除';

    DELETE FROM [dbo].[LeaveBalances];
    PRINT N'  LeaveBalances 已清除';

    DELETE FROM [dbo].[LeaveRequests];
    PRINT N'  LeaveRequests 已清除';

    DELETE FROM [dbo].[UserRoles];
    PRINT N'  UserRoles 已清除';

    DELETE FROM [dbo].[Employees];
    PRINT N'  Employees 已清除';

    DELETE FROM [dbo].[Departments];
    PRINT N'  Departments 已清除';

    DELETE FROM [dbo].[LeaveTypes];
    PRINT N'  LeaveTypes 已清除';

    DELETE FROM [dbo].[Roles];
    PRINT N'  Roles 已清除';

    DELETE FROM [dbo].[Users];
    PRINT N'  Users 已清除';

    PRINT N'=== Step 3: 插入資料 (正向相依順序) ===';


    -- ========================================
    -- 3a. Users
    -- ========================================
    PRINT N'  插入 Users...';

