    PRINT N'=== Step 4: 重設 Identity Seed ===';

    DECLARE @maxId INT;

    SELECT @maxId = MAX(Id) FROM [dbo].[Users];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[Users]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[Roles];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[Roles]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[UserRoles];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[UserRoles]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[Departments];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[Departments]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[Employees];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[Employees]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[LeaveTypes];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[LeaveTypes]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[LeaveRequests];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[LeaveRequests]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[LeaveBalances];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[LeaveBalances]', RESEED, @maxId);

    SELECT @maxId = MAX(Id) FROM [dbo].[LeaveAttachments];
    IF @maxId IS NOT NULL DBCC CHECKIDENT ('[dbo].[LeaveAttachments]', RESEED, @maxId);

    PRINT N'  Identity Seed 已重設';

    PRINT N'=== Step 5: 重新啟用外鍵約束 ===';

    ALTER TABLE [dbo].[Departments] WITH CHECK CHECK CONSTRAINT [FK_Dept_Manager];
    ALTER TABLE [dbo].[Employees] WITH CHECK CHECK CONSTRAINT [FK_Employees_Dept];
    ALTER TABLE [dbo].[Employees] WITH CHECK CHECK CONSTRAINT [FK_Employees_Manager];
    ALTER TABLE [dbo].[Employees] WITH CHECK CHECK CONSTRAINT [FK_Employees_Users];
    ALTER TABLE [dbo].[Employees] WITH CHECK CHECK CONSTRAINT [FK_Employees_WorkDel];
    ALTER TABLE [dbo].[LeaveAttachments] WITH CHECK CHECK CONSTRAINT [FK_Attach_Request];
    ALTER TABLE [dbo].[LeaveBalances] WITH CHECK CHECK CONSTRAINT [FK_Balance_Employee];
    ALTER TABLE [dbo].[LeaveBalances] WITH CHECK CHECK CONSTRAINT [FK_Balance_LeaveType];
    ALTER TABLE [dbo].[LeaveRequests] WITH CHECK CHECK CONSTRAINT [FK_Leave_ApprovedBy];
    ALTER TABLE [dbo].[LeaveRequests] WITH CHECK CHECK CONSTRAINT [FK_Leave_Employee];
    ALTER TABLE [dbo].[LeaveRequests] WITH CHECK CHECK CONSTRAINT [FK_Leave_LeaveDelegate];
    ALTER TABLE [dbo].[LeaveRequests] WITH CHECK CHECK CONSTRAINT [FK_Leave_LeaveType];
    ALTER TABLE [dbo].[UserRoles] WITH CHECK CHECK CONSTRAINT [FK_UserRoles_Role];
    ALTER TABLE [dbo].[UserRoles] WITH CHECK CHECK CONSTRAINT [FK_UserRoles_User];
    ALTER TABLE [dbo].[Members] WITH CHECK CHECK CONSTRAINT [FK_Members_Users];
    ALTER TABLE [dbo].[Instructors] WITH CHECK CHECK CONSTRAINT [FK_Instructors_Users];
    ALTER TABLE [dbo].[Notifications] WITH CHECK CHECK CONSTRAINT [FK_Notifications_Users_Receiver];
    ALTER TABLE [dbo].[Notifications] WITH CHECK CHECK CONSTRAINT [FK_Notifications_Users_Sender];
    ALTER TABLE [dbo].[UserExternalLogins] WITH CHECK CHECK CONSTRAINT [FK_ExternalLogins_Users];
    ALTER TABLE [dbo].[RoleFunctions] WITH CHECK CHECK CONSTRAINT [FK_RoleFunctions_Role];

    PRINT N'  外鍵約束已重新啟用';

    PRINT N'=== Step 6: 驗證資料筆數 ===';

    SELECT 'Users' AS [Table], COUNT(*) AS [Count] FROM [dbo].[Users]
    UNION ALL SELECT 'Roles', COUNT(*) FROM [dbo].[Roles]
    UNION ALL SELECT 'UserRoles', COUNT(*) FROM [dbo].[UserRoles]
    UNION ALL SELECT 'Departments', COUNT(*) FROM [dbo].[Departments]
    UNION ALL SELECT 'Employees', COUNT(*) FROM [dbo].[Employees]
    UNION ALL SELECT 'LeaveTypes', COUNT(*) FROM [dbo].[LeaveTypes]
    UNION ALL SELECT 'LeaveRequests', COUNT(*) FROM [dbo].[LeaveRequests]
    UNION ALL SELECT 'LeaveBalances', COUNT(*) FROM [dbo].[LeaveBalances]
    UNION ALL SELECT 'LeaveAttachments', COUNT(*) FROM [dbo].[LeaveAttachments]
    ORDER BY [Table];

    COMMIT TRANSACTION;
    PRINT N'';
    PRINT N'==========================================';
    PRINT N'  資料同步完成!';
    PRINT N'==========================================';

END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    PRINT N'';
    PRINT N'==========================================';
    PRINT N'  錯誤! 所有變更已回滾 (ROLLBACK)';
    PRINT N'==========================================';
    PRINT N'錯誤訊息: ' + ERROR_MESSAGE();
    PRINT N'錯誤行號: ' + CAST(ERROR_LINE() AS NVARCHAR(10));
    PRINT N'錯誤嚴重性: ' + CAST(ERROR_SEVERITY() AS NVARCHAR(10));
END CATCH
GO
